/// <summary>
/// Class for building a dialog out of a data contract
/// </summary>
class OMGMessagetypeParameterDialog
{
    OMGMessageTypeTable             oMGMessageTypeTable;
    OMGDirection                    direction;
    SysDictClass                    sysDictDataContractClass;    
    MethodName                      dataContractMethodName = 'dataContractClass';
    Object                          dataContractObject;
    ClassId                         dataContractClassId;
    OMGSerializedParameterContract  serializedParameterContract;
}

Method.Source:
public static void main(Args    _args)
{
    OMGMessagetypeParameterDialog   messagetypeParameterDialog = OMGMessagetypeParameterDialog::construct();        
    ;

    messagetypeParameterDialog.parmOMGMessageTypeTable(_args.record());
    messagetypeParameterDialog.parmDirection(_args.parmEnum());
    messagetypeParameterDialog.run();
}

public OMGDirection parmDirection(OMGDirection _direction = direction)
{
    direction = _direction;
    return direction;
}

public OMGMessageTypeTable parmOMGMessageTypeTable(OMGMessageTypeTable _oMGMessageTypeTable = oMGMessageTypeTable)
{
    oMGMessageTypeTable = _oMGMessageTypeTable;
    return oMGMessageTypeTable;
}

public static OMGMessagetypeParameterDialog construct()
{
    return new OMGMessagetypeParameterDialog();
}

/// <summary>
/// Kicks off the building of the dialog, and updates the message type if the user hits ok on the dialog form
/// </summary>
public void run()
{
    OMGContractUIBuilderBase    contractUIBuilder = OMGContractUIBuilderBase::construct();

    if (this.initContract())
    {
        contractUIBuilder.parmDataContractClassId(dataContractClassId);
        contractUIBuilder.parmSerializedInputContract(serializedParameterContract);
        if (contractUIBuilder.run())
        {
            this.updateMessageType(contractUIBuilder.getSerializedOutputContract());
        }
    }
}

/// <summary>
/// Initializes the data contract connected to the transport handler class
/// </summary>
/// <returns>Trus if all ok</returns>
public boolean initContract()
{
    ClassId         transportClassId;
    SysDictClass    sysDictClass;
    Object          messageHandlerObject;
    boolean         ret;

    if (direction == OMGDirection::Inbound)
    {
        transportClassId            = className2Id(oMGMessageTypeTable.InboundMessageTransportClass);
        serializedParameterContract = oMGMessageTypeTable.InboundSerializedParameterContract;
    }
    else
    {
        transportClassId            = className2Id(oMGMessageTypeTable.OutboundMessageTransportClass);
        serializedParameterContract = oMGMessageTypeTable.OutboundSerializedParameterContract;
    }
    if (transportClassId)
    {
        sysDictClass                    = new SysDictClass(transportClassId);
        messageHandlerObject = sysDictClass.makeObject();

        if (sysDictClass.hasObjectMethod(dataContractMethodName))
        {
            dataContractClassId                 = sysDictClass.callObject(dataContractMethodName, messageHandlerObject);
            sysDictDataContractClass            = new SysDictClass(dataContractClassId);
            ret = true;
        }
    }
    return ret;
}

/// <summary>
/// Updates the message type with the parameter contract values
/// </summary>
/// <param name = "_serializedParameterContract">The serialized parameter contract</param>
public void updateMessageType(OMGSerializedParameterContract  _serializedParameterContract)
{
    OMGMessageTypeTable             oMGMessageTypeTableUpdate;

    ttsbegin;

    oMGMessageTypeTableUpdate = OMGMessageTypeTable::find(oMGMessageTypeTable.MessageTypeId, true);

    if (oMGMessageTypeTableUpdate)
    {

        if (direction == OMGDirection::Outbound)
        {
            oMGMessageTypeTableUpdate.OutboundSerializedParameterContract = _serializedParameterContract;
        }
        else
        {
            oMGMessageTypeTableUpdate.InboundSerializedParameterContract  = _serializedParameterContract;
        }
        oMGMessageTypeTableUpdate.update();
    }

    ttscommit;
}
